def ts(t):
    h=int(t//3600); m=int(t%3600//60); s=t%60
    return f"{h:02d}:{m:02d}:{int(s):02d},{int(round((s-int(s))*1000)):03d}"
def wrap(t):
    ls=textwrap.wrap(t,42)
    if len(ls)>2:  # due righe al massimo: spezzo a metà
        w=t.split(); k=len(w)//2; ls=[' '.join(w[:k]),' '.join(w[k:])]
    return '\n'.join(ls)
here=os.path.dirname(os.path.abspath(__file__))
for lang,idx in (('it',2),('en',3)):
    out=[]
    for i,c in enumerate(C,1):
        assert c[1]>c[0] and (i==1 or c[0]>=C[i-2][1]), c
        out.append(f"{i}\n{ts(c[0])} --> {ts(c[1])}\n{wrap(c[idx])}\n")
    open(f"{here}/VociVere_te_long.{lang}.srt","w").write('\n'.join(out))
